using System;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 readonly List<FootingTakeoff> wallFootingResults=new List<FootingTakeoff>();List<StockAllocation> wallFootingPlan=new List<StockAllocation>();readonly List<BillQuantity> leanSources=new List<BillQuantity>();NumericUpDown leanThickness;
 void AddWallFootingWorks(){var item=NewExtraGrid("WallFooting","Wall Footing Estimate","Wall Footing",new[]{"Footing ID","Description / location","Length m","Width m","Thickness mm","Qty","Excavation depth m (blank=auto)","Formed sides?","X diameter mm","X input method","X spacing mm / bar count","Y diameter mm","Y input method","Y spacing mm / bar count","Rebar layers (1/2)","Total end allowance mm","Lean concrete?","Concrete m3","Forms m2","Rebar NET kg","Rebar BUY kg","Excavation bank m3","Backfill space m3","Gravel installed m3","Lean concrete m3","Status"},17,new Dictionary<int,string>{{4,"300"},{5,"1"},{7,"True"},{8,"16"},{9,"Spacing (mm)"},{10,"150"},{11,"16"},{12,"Spacing (mm)"},{13,"150"},{14,"1"},{15,"0"},{16,"False"}},"Strip/wall footing: L × width × thickness × qty. X bars run along L; Y across width. Select spacing OR bar count, one/two layers. Excavation allowance 0.30m each side; gravel 0.10m below footing. Auto depth includes selected lean concrete; entered depth must fit all layers. Exclude overlapping pits. Concrete uses the separate Wall Footing pay-item group; lean volume is separate 901(1).");ExtraCheck(item.Grid,7);ExtraCheck(item.Grid,16);ExtraChoice(item.Grid,9,"Spacing (mm)","Number of bars");ExtraChoice(item.Grid,12,"Spacing (mm)","Number of bars");ExtraChoice(item.Grid,14,"1","2");
  int column=footings.Columns.Add(new DataGridViewCheckBoxColumn{Name="Lean concrete?",HeaderText="Lean concrete?",Width=110,ReadOnly=false});footings.Columns[column].DisplayIndex=6;
  footings.CurrentCellDirtyStateChanged+=(s,e)=>{if(footings.CurrentCell!=null&&footings.CurrentCell.ColumnIndex==column&&footings.IsCurrentCellDirty)footings.CommitEdit(DataGridViewDataErrorContexts.Commit);};footings.CellValueChanged+=(s,e)=>{if(extraReady&&!filling&&e.ColumnIndex==column)Recalculate();};
 }
 void RecalculateWallFooting(ExtraWorkGrid item,DataGridViewRow row){var cfg=ExtraConfiguration("Wall Footing");double t=Number(row,4)/1000,lean=Cell(row,16)!=""&&bool.Parse(Cell(row,16))?(double)leanThickness.Value/1000:0,depth=OptionalNumber(row,6,t+.1+lean);if(depth<t+.1+lean-1e-9)throw new Exception("Excavation depth must include footing, gravel and lean concrete.");var x=MiscStructureTakeoff.Bars(Count(row,8),Cell(row,9),Number(row,10));var y=MiscStructureTakeoff.Bars(Count(row,11),Cell(row,12),Number(row,13));int layers=Count(row,14);if(layers<1||layers>2)throw new Exception("Choose one or two rebar layers.");var bars=new[]{x,y,layers==2?x:new FootingBarSpec(),layers==2?y:new FootingBarSpec()};var q=FootingTakeoff.Calculate(Cell(row,0),Cell(row,1),Number(row,2),Number(row,3),t,Count(row,5),depth,(double)extraMaterials["Wall Footing"].Cover.Value,Cell(row,7)!=""&&bool.Parse(Cell(row,7)),bars,OptionalNumber(row,15)/1000,cfg,(double)borrowSwell.Value,(double)borrowShrink.Value,(double)suitableSoil.Value);q.Soil.Source="Wall footing";q.Steel.Beam="Wall footing "+q.Id;double leanVolume=q.Length*q.Width*lean*q.Quantity;q.Backfill-=leanVolume;q.Soil.Fill=q.Backfill;q.Soil.Validate();row.Tag=q;wallFootingResults.Add(q);wallFootingPlan.AddRange(CommercialBars.Allocate(new[]{q.Steel},cfg,miscStock));row.Cells[17].Value=q.Concrete;row.Cells[18].Value=q.Forms;row.Cells[19].Value=q.Steel.Result.Total;row.Cells[21].Value=q.Excavation;row.Cells[22].Value=q.Backfill;row.Cells[23].Value=q.Gravel;row.Cells[24].Value=leanVolume;row.Cells[25].Value="Estimated";if(leanVolume>0)leanSources.Add(new BillQuantity{Description="Wall footing "+q.Id+" | lean concrete",Quantity=leanVolume,Unit="m3",Computation="L × width × lean thickness × qty"});}
 void ApplyExtraFoundationEarthworks(){if(!extraReady)return;foreach(DataGridViewRow row in footings.Rows){var q=row.Tag as FootingTakeoff;if(q==null||row.Cells[36].Value==null||!Convert.ToBoolean(row.Cells[36].Value))continue;try{double thickness=(double)leanThickness.Value/1000;if(thickness<=0)throw new Exception("Lean-concrete thickness must be positive when selected.");if(Cell(row,6)==""){q.Depth+=thickness;q.Excavation=(q.Length+.6)*(q.Width+.6)*q.Depth*q.Quantity;}else if(q.Depth<q.Thickness+.1+thickness-1e-9)throw new Exception("Entered pit depth does not fit footing, gravel and lean concrete.");double volume=q.Length*q.Width*thickness*q.Quantity;q.Backfill=q.Excavation-q.Concrete-q.Gravel-volume;q.Soil.Bank=q.Excavation;q.Soil.Fill=q.Backfill;q.Soil.Validate();row.Cells[31].Value=q.Excavation;row.Cells[34].Value=q.Backfill;leanSources.Add(new BillQuantity{Description="Footing "+q.Id+" | lean concrete",Quantity=volume,Unit="m3",Computation="L × width × lean thickness × qty; separate from structural concrete"});}catch(Exception ex){row.Cells[32].Value=ex.Message;errors.Add("Footing "+q.Id+": "+ex.Message);}}
  earthSources.AddRange(wallFootingResults.Select(q=>q.Soil));try{earthBalance=EarthworkBalance.Calculate(earthSources,(double)borrowSwell.Value,(double)borrowShrink.Value);earthBalanceGrid.Rows.Clear();foreach(var row in EarthSummaryRows().Take(6))earthBalanceGrid.Rows.Add(row);UpdateGravelSummary();}catch(Exception ex){errors.Add("Additional foundation earthworks: "+ex.Message);}
 }
 void UpdateWallFootingPurchase(){foreach(DataGridViewRow row in extraGrids["WallFooting"].Grid.Rows){var q=row.Tag as FootingTakeoff;if(q==null)continue;var stock=wallFootingPlan.Where(a=>a.Entry==q.Steel).ToList();row.Cells[20].Value=stock.Sum(a=>a.Purchase);if(stock.Any(a=>a.Choice==null)){row.Cells[25].Value="Unresolved commercial rebar cut";errors.Add("Wall footing "+q.Id+": unresolved stock cut.");}}}
 void WritePadLean(XmlElement root){var section=root.OwnerDocument.CreateElement("FootingLean");root.AppendChild(section);foreach(DataGridViewRow row in footings.Rows)if(!row.IsNewRow&&row.Cells[36].Value!=null&&Convert.ToBoolean(row.Cells[36].Value)){var entry=root.OwnerDocument.CreateElement("Entry");entry.SetAttribute("row",row.Index.ToString(CultureInfo.InvariantCulture));section.AppendChild(entry);}}
 void ReadPadLean(XmlElement root){foreach(DataGridViewRow row in footings.Rows)if(!row.IsNewRow)row.Cells[36].Value=false;var section=root["FootingLean"];if(section==null)return;var seen=new HashSet<int>();foreach(XmlElement entry in section.SelectNodes("Entry")){int index=int.Parse(entry.GetAttribute("row"),CultureInfo.InvariantCulture);if(index<0||index>=footings.Rows.Count||footings.Rows[index].IsNewRow||!seen.Add(index))throw new Exception("Invalid saved lean-concrete footing reference.");footings.Rows[index].Cells[36].Value=true;}}
}
}
